def planned_sets_for_existing_logs(apps, schema_editor):
    """Logs written before phase 12 only knew the plan: one set row per planned set."""
    ExerciseLog = apps.get_model("training", "ExerciseLog")
    ExerciseSet = apps.get_model("training", "ExerciseSet")
    batch = []
    for log in ExerciseLog.objects.filter(sets__isnull=True).iterator():
        batch.extend(
            ExerciseSet(log_id=log.id, number=number, reps=log.reps_completed)
            for number in range(1, log.sets_completed + 1)
        )
        if len(batch) >= 2000:
            ExerciseSet.objects.bulk_create(batch)
            batch = []
    ExerciseSet.objects.bulk_create(batch)
    # reps_completed was the planned reps per set; from now on it is the total of the session.
    ExerciseLog.objects.update(reps_completed=F("reps_completed") * F("sets_completed"))


def back_to_reps_per_set(apps, schema_editor):
    ExerciseLog = apps.get_model("training", "ExerciseLog")
    for log in ExerciseLog.objects.exclude(sets_completed=0).iterator():
        log.reps_completed = log.reps_completed // log.sets_completed
        log.save(update_fields=["reps_completed"])


